#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_print_number_negative_digits_print_all(void) {
    // Setup: number array with no leading zeros, num_digits_to_print = -1
    uint8_t N = 5;
    uint8_t number[] = {1, 2, 3, 4, 5}; // Little-endian: 54321
    int8_t num_digits_to_print = -1;

    // Forward declare stdout_capture_t from helpers.c
    typedef struct stdout_capture_t stdout_capture_t;
    // Capture stdout to verify output
    stdout_capture_t *cap = capture_stdout_start();
    TEST_ASSERT_NOT_NULL(cap);

    // Test: call function under test
    int result = print_number(number, N, num_digits_to_print);

    // Stop capture and get output
    char *output = capture_stdout_stop(cap);
    TEST_ASSERT_NOT_NULL(output);

    // Assertions
    TEST_ASSERT_EQUAL_INT(0, result); // Should succeed
    TEST_ASSERT_EQUAL_STRING("54321
", output); // Should print all digits

    // Cleanup
    free(output);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_print_number_negative_digits_print_all);
    return UNITY_END();
}

